CREATE TABLE `zimalofo_apiboxes`.`box1` (`id` INT NOT NULL AUTO_INCREMENT , `zeit` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP , `temperatur` FLOAT NOT NULL , `luftfeuchtigkeit` FLOAT NOT NULL , `bewegung` BOOLEAN NOT NULL , `lautstaerke` FLOAT NOT NULL , `magnet` BOOLEAN NOT NULL , `helligkeit` FLOAT NOT NULL , `alkohol` FLOAT NOT NULL , `lage_x` FLOAT NOT NULL , `lage_y` FLOAT NOT NULL , `gewicht` FLOAT NOT NULL , `co2` INT NOT NULL , `luftdruck` FLOAT NOT NULL , `distanz` INT NOT NULL , PRIMARY KEY (`id`)) ENGINE = InnoDB;